import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"Product Scope And Architecture","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"en/architecture/lab-word.md","filePath":"en/architecture/lab-word.md"}'),i={name:"en/architecture/lab-word.md"};function o(d,e,s,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="product-scope-and-architecture" tabindex="-1">Product Scope And Architecture <a class="header-anchor" href="#product-scope-and-architecture" aria-label="Permalink to &quot;Product Scope And Architecture&quot;">​</a></h1><p>Lab Word is a laboratory digital twin. The current stage focuses on equipment model presentation. Placement and live state with explicit sources follow later. See the <a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/CONTEXT.md" target="_blank" rel="noreferrer">glossary</a>.</p><h2 id="models-and-equipment" tabindex="-1">Models And Equipment <a class="header-anchor" href="#models-and-equipment" aria-label="Permalink to &quot;Models And Equipment&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab Word</span></span>
<span class="line"><span>  └─ Lab Viewer</span></span>
<span class="line"><span>       └─ Lab Layout</span></span>
<span class="line"><span>            └─ Equipment Instance ──uses──&gt; Equipment Model</span></span></code></pre></div><p>An Equipment Model is a reusable 3D asset; an Equipment Instance is one device with its own identity and position. Multiple instances can share one model, so filenames cannot stand in for equipment identity. The current single-model preview does not establish persistent layouts.</p><h2 id="existing-implementation-and-planned-integration" tabindex="-1">Existing Implementation And Planned Integration <a class="header-anchor" href="#existing-implementation-and-planned-integration" aria-label="Permalink to &quot;Existing Implementation And Planned Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Current state</th><th>Future responsibility</th></tr></thead><tbody><tr><td>Universal shell, identity, membership, knowledge</td><td>Existing application code</td><td>Host Lab and provide shared capabilities</td></tr><tr><td>Lab Viewer v1</td><td>Accepted isolated preview</td><td>Integrate import, camera, selection and metrics</td></tr><tr><td>Lab navigation and default entry after login</td><td>Agreed; integration acceptance pending</td><td>Explicitly compose the Lab contribution</td></tr><tr><td>Multiple-device layouts and real device data</td><td>Future scope</td><td>Define persistence and state sources</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>chooses the existing SaaS foundation: Lab owns equipment and layout behavior while Core owns common identity and membership. Production Lab integration and acceptance are pending. See <a href="./project-structure">project structure</a> for integration locations.</p><h2 id="presentation-boundaries" tabindex="-1">Presentation Boundaries <a class="header-anchor" href="#presentation-boundaries" aria-label="Permalink to &quot;Presentation Boundaries&quot;">​</a></h2><p>The first version inspects one self-contained GLB, with file selection/drop, automatic centering/framing, orbit/zoom/pan, click selection, return to preset and renderer metrics. Imported files remain in the browser session; server upload and a cloud asset library are outside this stage.</p><p>Preserve source scale. Missing external resources, absent geometry and decoder failures require explicit feedback while keeping the previous usable model. Replacements and page exit must release exclusive GPU resources; older loads must not overwrite newer models. These are acceptance contracts awaiting production implementation.</p><p>Three.js code will load with the Lab page and be measured against production bundle budgets. Preview builds and software-rendering measurements do not establish production performance.</p><h2 id="continue-development" tabindex="-1">Continue Development <a class="header-anchor" href="#continue-development" aria-label="Permalink to &quot;Continue Development&quot;">​</a></h2><p>Follow the <a href="./../guides/lab-viewer">preview guide</a>, then turn accepted behavior into public tests. The <a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/docs/plans/lab-viewer-m0.md" target="_blank" rel="noreferrer">presentation plan</a> records scope and assets; <a href="./module-boundaries">module boundaries</a> define ownership.</p><hr><p>Source version：<code>55a27be3bc71</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/docs/architecture/lab-word.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,16)])])}const h=t(i,[["render",o]]);export{b as __pageData,h as default};
